503	/** Send the working model list to PUT /api/models. */
504	function mrDoSave() {
505	  var saveBtn = document.getElementById('mr-save-btn');
506	  var msgEl   = document.getElementById('mr-msg');
507	  if (saveBtn) saveBtn.disabled = true;
508	  if (msgEl)   msgEl.innerHTML  = '<span style="color:var(--color-text-muted);font-size:13px;">Saving…</span>';
509	
510	  /* Client-side duplicate-slug pre-check: detect duplicates before sending to server */
511	  var activeModels = (mrModels || []).filter(function (m) { return !m._deleted; });
512	  var slugsSeen = {};
513	  var duplicateSlugs = [];
514	  activeModels.forEach(function (m) {
515	    if (slugsSeen[m.slug]) {
516	      if (duplicateSlugs.indexOf(m.slug) === -1) duplicateSlugs.push(m.slug);
517	    } else {
518	      slugsSeen[m.slug] = true;
519	    }
520	  });
521	  if (duplicateSlugs.length > 0) {
522	    if (saveBtn) saveBtn.disabled = false;
523	    if (msgEl) {
524	      msgEl.innerHTML = '<p class="error-banner">Duplicate slug' +
525	        (duplicateSlugs.length > 1 ? 's' : '') + ': ' +
526	        duplicateSlugs.map(function (s) { return '<code>' + escapeHtml(s) + '</code>'; }).join(', ') +
527	        '. Each model must have a unique slug.</p>';
528	    }
529	    return;
530	  }
531	
532	  /* Strip the internal _deleted sentinel from entries that are being removed;
533	     the server expects a plain array where absent entries are deletions. */
534	  var payload = activeModels.map(function (m) {
535	    return { id: m.id, name: m.name, slug: m.slug, cc_model: m.cc_model };
536	  });
537	
538	  API.saveModels(payload)
539	    .then(function (result) {
540	      /* Refresh state from server response */
541	      var saved = (result && result.models) ? result.models : payload;
542	      mrModels   = mrCloneModels(saved);
543	      mrOriginal = mrCloneModels(saved);
544	      mrEditingId = null;
545	      configDirty.modelRegistry = false;
546	      mrRefreshTab();
547	      /* Show success message */
548	      var msg2 = document.getElementById('mr-msg');
549	      if (msg2) msg2.innerHTML = '<span class="success-banner" style="display:inline-block;padding:4px 10px;">Saved successfully.</span>';
550	    })
551	    .catch(function (err) {
552	      var msg2 = document.getElementById('mr-msg');
